def strategy(history, rng):
    n = len(history)
    if n < 4:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_last = opp[-1]
    my_last = my[-1]

    if 'D' not in opp:
        return 'C'

    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'

    if n > 90 and opp_last == 'D':
        return 'D'

    opp_c = opp.count('C')
    opp_coop_rate = opp_c / n

    recent_len = min(n, 10)
    recent = opp[-recent_len:]
    recent_c = recent.count('C')
    recent_rate = recent_c / recent_len

    if opp_coop_rate < 0.25 or recent_rate < 0.25:
        return 'D'

    if opp_coop_rate > 0.8 and recent_rate > 0.6:
        return 'C'

    if opp_last == 'C':
        return 'C'
    else:
        if my_last == 'D':
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            return 'D'
